"""Ordinary native constraints generated by the direct offset dimension gesture."""

import copy
import importlib
import json
import sys
import types
from pathlib import Path

import pytest

from mechanical_cad.sidecar import process_request

ROOT = Path(__file__).resolve().parents[2]
package = types.ModuleType("mcad_offset_test")
package.__path__ = [str(ROOT / "blender_addon/mechanical_cad_blender")]
sys.modules[package.__name__] = package
commands = importlib.import_module(package.__name__ + ".general_sketch_commands")
drafts = importlib.import_module(package.__name__ + ".general_sketch_draft")
helper = importlib.import_module(package.__name__ + ".point_line_dimension")


def fixture():
    draft = drafts.GeneralSketchDraft(
        json.dumps(
            {
                "schema_version": 1,
                "id": "part",
                "name": "Part",
                "units": "mm",
                "parameters": {},
                "features": [],
                "active_feature": None,
            }
        )
    )
    lines = []
    for a, b in [((0, 0), (20, 0)), ((0, -10), (0, 20))]:
        lines.append(
            draft.execute(
                commands.AddProjectionGeometry(
                    "line", (commands.PointSeed(*a), commands.PointSeed(*b))
                )
            ).entity_ids[-1]
        )
    center, circle = draft.execute(commands.AddCircle(commands.PointSeed(7, 5), 2)).entity_ids
    return draft, center, circle, lines


def solve(draft):
    response = process_request(draft.solve_request())
    assert response["ok"], response
    return response["result"]["sketch"]


def test_two_offsets_edit_and_atomic_undo_redo_checkpoint():
    draft, center, circle, lines = fixture()
    before = draft.sketch
    relation_ids = []
    for line, foot, distance in [(lines[0], (7, 0), 5), (lines[1], (0, 5), 7)]:
        outcome = draft.execute(
            commands.AddPointLineDimension(center, line, commands.PointSeed(*foot), distance)
        )
        relation_ids.append(outcome.constraint_id)
    report = solve(draft)
    assert report["remaining_dof"] == 1  # Only radius is free; helpers introduce no free DOF.
    restored = drafts.GeneralSketchDraft.from_checkpoint_payload(draft.checkpoint_payload())
    assert restored.sketch == draft.sketch
    # The reference anchors and lines have not moved or acquired edited drivers.
    assert restored.sketch["points"][:4] == before["points"][:4]
    assert restored.sketch["lines"][:2] == before["lines"]
    assert restored.sketch["constraints"][:4] == before["constraints"]
    before_duplicate = copy.deepcopy(restored.checkpoint_payload())
    duplicate = restored.execute(
        commands.AddPointLineDimension(center, lines[0], commands.PointSeed(7, 0), 5)
    )
    assert not duplicate.changed and duplicate.constraint_id == relation_ids[0]
    assert restored.checkpoint_payload() == before_duplicate
    restored.undo()
    assert len(restored.sketch["points"]) == len(before["points"]) + 1
    assert relation_ids[1] not in {c["id"] for c in restored.sketch["constraints"]}
    restored.undo()
    assert restored.sketch == before
    restored.redo()
    restored.redo()
    request = restored.solve_request()
    for c in request["document"]["features"][-1]["sketch"]["constraints"]:
        if c["id"] == relation_ids[0]:
            c["value"] = 9
    response = process_request(request)
    assert response["ok"], response
    solved = response["result"]["sketch"]["solved"]
    point = next(p for p in solved["points"] if p["id"] == center)
    assert (point["u"], point["v"]) == pytest.approx((7, 9))
    assert all(line.get("construction") for line in solved["lines"])


def test_oblique_foot_and_degenerate_rejection():
    foot, distance = helper.perpendicular_foot((4, 0), (0, 0), (4, 4))
    assert foot == pytest.approx((2, 2))
    assert distance == pytest.approx(8**0.5)
    with pytest.raises(ValueError, match="zero offset"):
        helper.perpendicular_foot((2, 2), (0, 0), (4, 4))
    with pytest.raises(ValueError, match="distinct endpoints"):
        helper.perpendicular_foot((2, 2), (0, 0), (0, 0))


def test_tampered_checkpoint_cannot_replace_reference_geometry():
    draft, center, _, lines = fixture()
    draft.execute(commands.AddPointLineDimension(center, lines[0], commands.PointSeed(7, 0), 5))
    # Strict reducer validates the compound scaffold, not just arbitrary add data.
    prepared = commands.prepare_command(
        draft.sketch,
        commands.AddPointLineDimension(center, lines[1], commands.PointSeed(0, 5), 7),
        draft.revision,
        set(),
        100,
    )
    record = copy.deepcopy(prepared.record)
    record["lines"][0]["construction"] = False
    with pytest.raises(commands.DraftError, match="inconsistent"):
        commands._apply_record(draft.sketch, record)


def test_oblique_offset_native():
    draft, center, _, _ = fixture()
    line = draft.execute(
        commands.AddProjectionGeometry(
            "line", (commands.PointSeed(-10, -10), commands.PointSeed(20, 20))
        )
    ).entity_ids[-1]
    foot, value = helper.perpendicular_foot((7, 5), (-10, -10), (20, 20))
    draft.execute(commands.AddPointLineDimension(center, line, commands.PointSeed(*foot), value))
    report = solve(draft)
    assert report["remaining_dof"] == 2
    assert report["max_residual_mm"] < 1e-6
